Md(a,b,c){return a+" "+b+u.b+c+" oran\u0131nda hasar."},
Me(a,b,c,d){return"%"+a+" \u015fansla "+b+" "+c+u.b+d+" oran\u0131nda hasar."},
MA(a,b){return a+" "+b+" boyunca [[Ayna]] verir: bir d\xfc\u015fman\u0131n sonraki zay\u0131flatmas\u0131 geri seker ve onu etkiler."},
Mr(a,b){return a+u.A+b+" daha uzun s\xfcrer."},
Ms(a,b,c){return"%"+a+" \u015fansla "+b+u.A+c+" daha uzun s\xfcrer."},
Mt(a,b,c){return a+" "+b+" boyunca [[Ya\u015fam K\u0131v\u0131lc\u0131m\u0131]] verir: d\xfc\u015fen hemen maks. <hp>can\u0131n</hp> %"+c+" oran\u0131yla aya\u011fa kalkar (sava\u015f ba\u015f\u0131na bir kez)."},
M5(a){return"Her kritik vuru\u015f bir daha vurur, en fazla "+a+" ek vuru\u015f."},
za(a){return"kritik zincir +"+a},
Vv(a){return"Bu Ovaling\u2019in <fx:heal>iyile\u015ftirmeleri</fx> ve <fx:shield>kalkanlar\u0131</fx> %"+a+" daha g\xfc\xe7l\xfcd\xfcr."},
W3(a){return"Her sava\u015f\u0131n ba\u015f\u0131nda t\xfcm tak\u0131m maks. <hp>can\u0131n</hp> %"+a+" oran\u0131nda bir <fx:shield>kalkan</fx> al\u0131r."},
V1(a){return"Kritik vuru\u015flar\u0131 hedefi 2 tur <fx:bleed>kanat\u0131r</fx>: her tur kendi <atk>sald\u0131r\u0131 g\xfcc\xfcn\xfcn</atk> %"+a+" oran\u0131nda hasar."},
Vo(a){return"<hp>Can\u0131</hp> %30\u2019un alt\u0131ndaki hedeflere +%"+a+" hasar."},
VG(a){return"Biri tak\u0131mdaki bir Ovaling\u2019i tam <hp>can\u0131n\u0131n</hp> \xfczerinde iyile\u015ftirirse fazlan\u0131n %"+a+" oran\u0131 <fx:shield>kalkan</fx> olur. En fazla maks. <hp>can\u0131n\u0131n</hp> %10\u2019u."},
VC(a){return"Turunun ba\u015f\u0131nda son turundan beri kaybetti\u011fi <hp>can\u0131n</hp> %"+a+" oran\u0131nda kendini <fx:heal>iyile\u015ftirir</fx>."},
VI(a){return"Tak\u0131mdaki herkes hayattayken t\xfcm tak\u0131m <fx:damage_reduction>%"+a+" daha az hasar</fx> al\u0131r."},
UO(a){return"Hayattayken tak\u0131m, birden fazla hedefe yap\u0131lan sald\u0131r\u0131lardan <fx:damage_reduction>%"+a+" daha az hasar</fx> al\u0131r."},
Vp(a){return"Tak\u0131mdaki bir Ovaling\u2019in <hp>can\u0131</hp> ilk kez %50\u2019nin alt\u0131na d\xfc\u015f\xfcnce hemen maks. <hp>can\u0131n\u0131n</hp> %"+a+" oran\u0131nda <fx:heal>iyile\u015fir</fx>. Her Ovaling i\xe7in sava\u015fta bir kez."},
VF(a){return"Hayattayken her d\xfc\u015fman\u0131n ilk sald\u0131r\u0131s\u0131 tak\u0131ma <fx:damage_reduction>%"+a+" daha az hasar</fx> verir. Kendi her 3. turunda bu yeniden ba\u015flar."},
VH(a){var s=""+a
return"Turlar\u0131n\u0131n ba\u015f\u0131nda s\u0131rayla: t\xfcm tak\u0131m 1 tur [[%"+s+" daha fazla <atk>sald\u0131r\u0131</atk>]] al\u0131r, bir sonrakinde 1 tur <fx:damage_reduction>%"+s+" daha az hasar</fx>."},
UT(a){return"Tak\u0131mdaki bir Ovaling <hp>can\u0131n\u0131n</hp> en az %15\u2019i kadar bir vuru\u015ftan sa\u011f \xe7\u0131karsa hemen <hp>can\u0131n\u0131n</hp> %"+a+" oran\u0131nda <fx:shield>kalkan</fx> al\u0131r."},
Va(a){return"Sava\u015f\u0131n ve her yeni dalgan\u0131n ba\u015f\u0131nda zaten [[%"+a+" tur \xe7ubu\u011fu]] vard\u0131r."},
VU(a){return"Kal\u0131c\u0131 olarak [[%"+a+" daha fazla <spd>h\u0131z</spd>]]."},
VB(a){return"<hp>Can\u0131</hp> %"+a+" oran\u0131ndan fazlayken d\xfc\u015fmanlar\u0131n tek hedefli sald\u0131r\u0131lar\u0131 <fx:taunt>K\u0131\u015fk\u0131rtma</fx> gibi ona gider. O s\u0131rada <fx:damage_reduction>%20 daha az hasar</fx> al\u0131r."},
V4(a){return"Hayattayken tak\u0131m\u0131na gelen kritik vuru\u015flar %"+a+" daha az ek hasar verir."},
Vf(a){return"Hayattayken d\xfc\u015fmanlar\u0131n tak\u0131m\u0131na verdi\u011fi her [!zay\u0131flatma!] %"+a+" \u015fansla seker ve g\xf6nderene d\xf6ner."},
UL(a){return"Bir m\xfcttefik bekleme s\xfcreli bir yetenek kullan\u0131nca [[%"+a+" tur \xe7ubu\u011fu]] kazan\u0131r."},
VY(a){return"Kendi her turunda %"+a+" \u015fansla tak\u0131mdaki en uzun bekleme s\xfcresi 1 tur k\u0131sal\u0131r. Her yetenek kullan\u0131m ba\u015f\u0131na en fazla 1 tur h\u0131zlan\u0131r."},
Vg(a){var s=null
return"Hayattayken tak\u0131m\u0131na gelen yeni [!zay\u0131flatmalar!] "+A.b_(a,s,this.a,s,"1 tur",""+a+" tur",s,s)+" daha k\u0131sa s\xfcrer, en az 1 tur. Ayr\u0131ca d\xf6rtte bir daha zay\u0131ft\u0131r."},
